{
  actions = [
    {
      command = "yo say 'Welcome home!'";
      type = "shell";
    }
  ];
  awayDuration = 7200;
  delay = 10;
  door = "Door Sensor Hall";
  enable = true;
  message = "contact";
}

{
  button_single_press = {
    actions = [
      {
        message = "{\"state\":\"TOGGLE\"}";
        topic = "zigbee2mqtt/living_room_lights/set";
        type = "mqtt";
      }
    ];
    description = "Toggle living room lights on single button press";
    enable = true;
    message = "single";
    topic = "zigbee2mqtt/living_room_button/action";
  };
  motion_alert = {
    actions = [
      "echo 'Motion detected outside!' | wall"
      {
        command = "/nix/store/hf9wcn7jhcynf4ihndzbscbknx97in30-libnotify-0.8.8/bin/notify-send 'Security' 'Motion detected outside'";
        type = "shell";
      }
    ];
    description = "Send notification on outdoor motion";
    enable = true;
    message = "true";
    topic = "zigbee2mqtt/outdoor_motion/occupancy";
  };
}

{
  kitchen_idle = {
    actions = [
      {
        scene = "kitchenFadeOff";
        type = "scene";
      }
      {
        message = "{\"state\":\"OFF\"}";
        topic = "zigduck/Fläkt/set";
        type = "mqtt";
      }
    ];
    conditions = [
      {
        room = "kitchen";
        type = "lights_on";
        value = true;
      }
    ];
    description = "Turn off kitchen lights and fan after 10 minutes with no motion";
    enable = true;
    motion_restored_actions = [
      {
        scene = "kitchenInstant";
        type = "scene";
      }
    ];
    motion_sensors = [
      "Motion Sensor Kök"
    ];
    no_motion_duration = 600;
  };
}

